schemas.schema-01-systematic.prisma:
/// Configuration settings for the discussion board system.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Configuration key.
  key String

  /// Configuration value.
  value String

  /// Description of the configuration.
  description String?

  /// Timestamp when the configuration was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the configuration was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
}

schemas.schema-02-actors.prisma:
/// Table storing information about registered users on the discussion board.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_registered_users {
  //----
  // COLUMNS
  //----
  /// Primary key for the registered users table.
  id String @id @db.Uuid

  /// Username chosen by the user during registration.
  username String

  /// Email address of the registered user.
  email String

  /// Hashed password for the user's account.
  password_hash String

  /// Indicates whether the user's account is active.
  is_active Boolean

  /// Timestamp when the user account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user account was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_registered_user_sessions discussion_board_registered_user_sessions[]
  discussion_board_comments discussion_board_comments[]
  discussion_board_comment_replies discussion_board_comment_replies[]
  discussion_board_reported_content discussion_board_reported_content[]

  @@unique([username])
  @@unique([email])
}

/// Table storing session information for registered users.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_registered_user_sessions {
  //----
  // COLUMNS
  //----
