  id String @id @db.Uuid

  /// Foreign key referencing the registered users table.
  registered_user_id String @db.Uuid

  /// IP address of the user during session creation.
  ip String

  /// URL from which the session was created.
  href String

  /// Referrer URL for the session.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  registeredUser discussion_board_registered_users @relation(fields: [registered_user_id], references: [id], onDelete: Cascade, map: "discussion_board_registered_user_sessions_registered_u_01934eee")

  // spellchecker: ignore-next-line
  @@index([registered_user_id, created_at], map: "discussion_board_registered_user_sessions_registered_u_89a80578")
