  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  comment discussion_board_comments @relation(fields: [discussion_board_comment_id], references: [id], onDelete: Cascade, map: "discussion_board_comment_replies_discussion_board_comm_d614b2a0")
  user discussion_board_registered_users @relation(fields: [discussion_board_user_id], references: [id], onDelete: Cascade)

  @@index([discussion_board_user_id])

  // spellchecker: ignore-next-line
  @@index([discussion_board_comment_id, created_at], map: "discussion_board_comment_replies_discussion_board_comm_eefbbb24")
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-05-moderation.prisma:
/// Table storing reported content from the discussion board. Includes
/// information about the reported content, the user who reported it, and the
/// reason for reporting.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_reported_content {
  //----
  // COLUMNS
  //----
  /// Primary key for the reported content table.
  id String @id @db.Uuid

  /// Foreign key referencing the article that was reported. {@link
  /// discussion_board_articles.id}.
  discussion_board_article_id String? @db.Uuid

  /// Foreign key referencing the comment that was reported. {@link
  /// discussion_board_comments.id}.
  discussion_board_comment_id String? @db.Uuid

  /// Foreign key referencing the user who reported the content. {@link
  /// discussion_board_registered_users.id}.
  discussion_board_registered_user_id String @db.Uuid

  /// Reason why the content was reported.
  report_reason String

  /// Timestamp when the report was made.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  article discussion_board_articles? @relation(fields: [discussion_board_article_id], references: [id], onDelete: Cascade, map: "discussion_board_reported_content_discussion_board_art_e80546ea")
  // spellchecker: ignore-next-line
  comment discussion_board_comments? @relation(fields: [discussion_board_comment_id], references: [id], onDelete: Cascade, map: "discussion_board_reported_content_discussion_board_com_0d5eec47")
  // spellchecker: ignore-next-line
  reportingUser discussion_board_registered_users @relation(fields: [discussion_board_registered_user_id], references: [id], onDelete: Cascade, map: "discussion_board_reported_content_discussion_board_reg_4108a942")

  discussion_board_moderation_actions discussion_board_moderation_actions[]

  // spellchecker: ignore-next-line
  @@index([discussion_board_article_id, created_at], map: "discussion_board_reported_content_discussion_board_art_17f2727e")
  // spellchecker: ignore-next-line
  @@index([discussion_board_comment_id, created_at], map: "discussion_board_reported_content_discussion_board_com_dad1ed74")
  // spellchecker: ignore-next-line
  @@index([discussion_board_registered_user_id, created_at], map: "discussion_board_reported_content_discussion_board_reg_d552dd45")
}

/// Table storing moderation actions taken on reported content. Includes
/// details about the action taken, the moderator who took it, and the
/// result.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary key for the moderation actions table.
