  /// Foreign key referencing the moderator who took the action. {@link
  /// discussion_board_moderators.id}.
  discussion_board_moderator_id String @db.Uuid

  /// The moderation action taken (e.g., approved, rejected, edited).
  action_taken String

  /// Result or additional information about the moderation action.
  result String?

  /// Timestamp when the moderation action was taken.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  reportedContent discussion_board_reported_content @relation(fields: [discussion_board_reported_content_id], references: [id], onDelete: Cascade, map: "discussion_board_moderation_actions_discussion_board_r_ea18e78f")
  // spellchecker: ignore-next-line
  moderator discussion_board_moderators @relation(fields: [discussion_board_moderator_id], references: [id], onDelete: Cascade, map: "discussion_board_moderation_actions_discussion_board_m_ba9da9dd")

  // spellchecker: ignore-next-line
  @@index([discussion_board_reported_content_id, created_at], map: "discussion_board_moderation_actions_discussion_board_r_65f05583")
  // spellchecker: ignore-next-line
