import type { IDiscussionBoardRegisteredUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRegisteredUser";

export async function test_api_comment_retrieval_by_id_not_found(
  connection: api.IConnection,
) {
  // Create a new registered user to authenticate the request
  const registeredUser: IDiscussionBoardRegisteredUser.IAuthorized =
    await api.functional.auth.registered_user.join(connection, {
      body: typia.random<IDiscussionBoardRegisteredUser.ICreate>(),
    });
  typia.assert(registeredUser);

  // Generate a random non-existent comment ID
  const nonExistentCommentId = typia.random<string & tags.Format<"uuid">>();

  // Attempt to retrieve the non-existent comment
  await TestValidator.error(
    "Retrieving non-existent comment should return 404",
    async () =>
      api.functional.discussionBoard.registeredUser.comments.at(connection, {
        commentId: nonExistentCommentId,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardRegisteredUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRegisteredUser";

export async function test_api_comment_creation_validation_failure(
  connection: api.IConnection,
) {
  // Create a registered user first
  const registeredUser: IDiscussionBoardRegisteredUser.IAuthorized =
    await api.functional.auth.registered_user.join(connection, {
      body: typia.random<IDiscussionBoardRegisteredUser.ICreate>(),
    });
  typia.assert(registeredUser);
  TestValidator.equals(
    "registered user email",
    registeredUser.email,
    registeredUser.email,
  );

  // Test case 1: Missing required 'content' field
  await TestValidator.error(
    "comment creation should fail with missing content",
    async () => {
      await api.functional.discussionBoard.registeredUser.comments.create(
        connection,
        {
          body: {
            discussion_board_article_id: typia.random<
              string & tags.Format<"uuid">
            >(),
          } as IDiscussionBoardComment.ICreate,
        },
      );
    },
  );

  // Test case 2: Empty content
  await TestValidator.error(
    "comment creation should fail with empty content",
    async () => {
      await api.functional.discussionBoard.registeredUser.comments.create(
        connection,
        {
          body: {
            content: "",
            discussion_board_article_id: typia.random<
              string & tags.Format<"uuid">
            >(),
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardRegisteredUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRegisteredUser";

export async function test_api_attachment_creation_for_article(
  connection: api.IConnection,
) {
  // Create a new registered user
  const registeredUser = await api.functional.auth.registered_user.join(
    connection,
    {
      body: typia.random<IDiscussionBoardRegisteredUser.ICreate>(),
    },
  );
  typia.assertGuard(registeredUser);

  // Create a new article using the registered user
  const article =
    await api.functional.discussionBoard.registeredUser.articles.create(
      connection,
      {
        body: typia.random<IDiscussionBoardArticle.ICreate>(),
      },
    );
  typia.assertGuard(article);

  // Create a new attachment for the article
  const attachmentData = {
    name: RandomGenerator.name(),
    url: `https://example.com/${RandomGenerator.alphaNumeric(8)}.jpg`,
  } satisfies IDiscussionBoardArticleAttachment.ICreate;

  const attachment =
    await api.functional.discussionBoard.articles.attachments.create(
      connection,
      {
        articleId: article,
        body: attachmentData,
      },
    );
  typia.assertGuard(attachment);

  // Validate the created attachment
  TestValidator.equals("attachment name", attachment.name, attachmentData.name);
  TestValidator.equals("attachment URL", attachment.url, attachmentData.url);
}

